@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

abstract class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

Person "1" -- "*" ResearchInstitution : works for

Person "1..*" -- "*" ScientificArticle : author
AuthorPosition -- "1" ScientificArticle
AuthorPosition -- "1" Person

Person "1" -- "*" PeerReviewedPaper : reviewer

TechnicalReport "*" -- "1" ResearchInstitution : published by

Publisher "1" *-- "*" Journal
ResearchInstitution "*" -- "*" Journal : subscribes to

PeerReviewedPaper "*" -- "1" Journal : published in

@enduml

